int quadtree_node_ispointer(quadtree_node_t *node)
{
    return node->nw != ((void *)0) && node->ne != ((void *)0) && node->sw != ((void *)0) && node->se != ((void *)0) &&
           !quadtree_node_isleaf(node);
}

